const items = $input.all();

if (items.length === 0) {
  return [{ json: { lastMessage: null } }];
}

const lastItem = items[0];

return [
  {
    json: {
      ...lastItem.json, // mantém os campos originais
      single: true      // flag para você saber que veio de um único item
    }
  }
];

// Pegar todos os itens do nó anterior (Execute a SQL query1)
const items = $input.all();

// Criar string com blocos numerados a partir do campo 'content'
let lastMessage = items
  .map((item, index) => `block de mensagem ${index + 1}: ${item.json.content || ''}`)
  .join('\n');  // cada bloco em nova linha

return [
  {
    json: {
      lastMessage: lastMessage
    }
  }
];

