let texto;
let data;
let leads = [];
let nomeLead;
let existe = false;

try {
  // Tenta obter o JSON de entrada
  texto = $input.first()?.json?.data;

  // Faz o parse do JSON se existir
  if (texto) data = JSON.parse(texto);

  // Acessa a lista de leads de forma segura
  leads = data?._embedded?.leads || [];

  // Pega o nome do lead do webhook, com fallback
  nomeLead = $('Credenciais').first()?.json?.body?.originalWebhook?.data?.pushName || '';

  // Verifica se algum lead tem o mesmo nome
  existe = leads.some((l) => l?.name === nomeLead);
} catch (error) {
  // Em caso de erro no JSON ou acesso, mantém valores padrão
  console.error('Erro ao processar leads:', error);
}

return [{ existe }];

