// Utilitário para obter data atual de São Paulo
function obterDataAtualSP() {
    const agora = new Date();

    // Data legível em pt-BR
    const dataLegivel = agora.toLocaleString('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });

    // Data ISO 8601 completa com fuso de São Paulo
    const dataISO = new Date(
        agora.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })
    ).toISOString().replace('Z', '-03:00');

    return {
        iso: dataISO,
        legivel: dataLegivel
    };
}

// Criando saída para n8n
const hoje = obterDataAtualSP();

// Retornar um array de objetos
return [
    {
        json: {
            iso: hoje.iso,
            legivel: hoje.legivel
        }
    }
];

